-- Optional MySQL 8 schema; H2 demo mode does not require this file.
CREATE DATABASE IF NOT EXISTS simpleshop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE simpleshop;
CREATE TABLE IF NOT EXISTS categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, description VARCHAR(3000), price DECIMAL(12,2) NOT NULL, stock INT NOT NULL, image_url VARCHAR(255), category_id BIGINT, CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, shipping_address VARCHAR(1000) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(255) NOT NULL, quantity INT NOT NULL, price DECIMAL(12,2) NOT NULL, CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(id), CONSTRAINT fk_item_product FOREIGN KEY(product_id) REFERENCES products(id));
